export const allStackFrames = function*(
		debug: boolean = false
		): TIterator<TStackFrame> {

	openDebugFile('stack')

	try {
		const oldLimit: number = Error.stackTraceLimit
		const oldPreparer = Error.prepareStackTrace
		Error.stackTraceLimit = 99
		Error.prepareStackTrace = (
				error: unknown,
				lCallSites: CallSite[]
				) => {

			assert((lCallSites.length > 0), "lCallSites is EMPTY")

			for (const site of lCallSites) {
				DBG(centered('fullCallSite', {char: '='}))
				DBG(fullCallSite(site))

				DBG(centered('getFrame', {char: '-'}))
				DBG(getFrame(site))
			}

			const lFrames: TStackFrame[] = []    // yield these values later

			fromFSM(
				lCallSites,
				[
					// --- state 0
					(site, i): TState => {
						const type = getFrameType(site)
						if ((type === 'for-next') || (type === 'for-from')) {
							return 0
						}
						if (type !== 'function') {
							return 0
						}
						const source = getFrameSource(site)
						if (matches(source, /\bv8-stack\.lib\.(?:ts|civet)$/)) {
							return 0
						}
						else {
							lFrames.push(getFrame(site))
							return 1
						}
					},

					// --- state 1
					(site, i): TState => {
						lFrames.push(getFrame(site))
						return 1
					}
					],
				(state) => { return lFrames },
				{})

			// --- fix a bug in the V8 engine where calls inside a
			//     top level anonymous function is reported as
			//     being of type 'script'

			const nFrames = lFrames.length
			let i1 = 0;for (const frame of lFrames) {const i = i1++;
				if ((i < nFrames-1) && (frame.type === 'script')) {
					frame.type = 'function'
				}
			}
			return lFrames
		}

		const obj: Object = {}
		Error.captureStackTrace(obj)
		// @ts-ignore
		const lStack: TStackFrame[] = obj.stack

		assert((lStack.length > 0), "EMPTY STACK")

		// --- reset to previous values
		Error.stackTraceLimit = oldLimit
		Error.prepareStackTrace = oldPreparer
		for (const frame of lStack) {
			DBG(frame)
			yield frame
		}
		return
	}

	catch (err) {
		ERR(`'ERROR in allStackFrames: ${getErrStr(err)}`)
		return
	}
	finally {
		closeDebugFile('stack')
	}
}

