export type TFrameType = (
	'for-next' |
	'for-from' |
	'unknown' |
	'external' |
	'eval' |
	'native' |
	'constructor' |
	'method' |
	'function' |
	'script'
	)

const getFrameType = (
		site: CallSite
		): TFrameType => {

	const source: (string | undefined) = site.getFileName()
	const type = (
		(()=>{if (defined(source)) {
			return (
			  source.startsWith('ext:') ? 'external'
			: site.getFunctionName()    ? 'function'
			: site.getMethodName()      ? 'method'
			: site.isTopLevel           ? 'script'
			: site.isEval()             ? 'eval'
			: site.isNative()           ? 'native'
			: site.isConstructor()      ? 'constructor'
			:                             'script'
			)
		}
		else {
			const name = (
					site.getFunctionName()
				|| site.getMethodName()
				|| ''
				)
			return (
			  (name === 'next') ? 'for-next'
			: (name === 'from') ? 'for-from'
			:                    'unknown'
			)
		}})()
		)
	return type
}

// ---------------------------------------------------------------------------

const getFrameName = (site: CallSite): string => {

	return (
			site.getFunctionName()
		|| site.getMethodName()
		|| ''
		)
}

// ---------------------------------------------------------------------------

const getFrameSource = (site: CallSite): string => {

	const src = site.getFileName()
	if (!src) {
		return ''
	}
	return src.startsWith('ext:') ? src : toRelPath(src || '')
}

