const hCache = new Map<string,RawSourceMap>()

export const mapPosSync = (filePos: TFilePosition): (TFilePosition | undefined) => {

	const {source, line, col} = filePos
	const contents = Deno.readTextFileSync(source)
	const hSrcMap = (
		(()=>{if (hCache.has(source)) {
			return hCache.get(source)
		}
		else {
			const [_, hSrcMap] = extractSourceMap(contents)
			return hSrcMap
		}})()
		)

	if (notdefined(hSrcMap)) {
		return undef
	}

	// --- add to the cache
	hCache.set(source, hSrcMap)

	const [fileNum, srcLine, srcCol] = getOrgPos(hSrcMap, line, col)
	const fileName = hSrcMap.sources[fileNum]
	if (notdefined(fileName)) {
		return undef
	}
	return {
		source: normalizePath(`${dirname(source)}/${fileName}`),
		line: srcLine,
		col: srcCol
		}
}

