// ---------------------------------------------------------------------------

export const frameHdr = (): string => {

	return sprintf("%-8s %-16s %s", 'type', 'name', 'source')
}

// ---------------------------------------------------------------------------

export const frameStr = (
		frame: TStackFrame,
		): string => {

	const posStr = (line: number, col: number): string => {
		return inUnitTest() ? `${line}:${col}` : green(`${line}:${col}`)
	}

	const {type, orgSource, orgLine, orgCol, source, line, col, name} = frame
	const typeStr = sprintf('%-8s', type)
	const nameStr = (
		((type === 'function') && !name?
			sprintf('%-16s', '<anon>')
		:
			sprintf('%-16s', name))
		)
	const prefix = `${typeStr} ${nameStr}`
	if (orgSource) {
		const mapped = (
			  (source === orgSource)
			? ''
			: `\n${' '.repeat(30)}=> ${source} ${posStr(line, col)}`
			)
		return `${prefix} ${orgSource} ${posStr(orgLine, orgCol)}` + mapped
	}
	else {
		return `${prefix} <none>`
	}
}

