export const v8StackStr = (
		lFrames: ((TStackFrame[]) | undefined) = undef,
		debug: boolean = false
		): string => {

	const results=[];for (const frame of (lFrames || allStackFrames(debug))) {
		results.push(frameStr(frame))
	};const lLines =results
	return [
		frameHdr(),
		'-'.repeat(68),
		...lLines,
		'-'.repeat(68)
		].join('\n')
}

