export const getMyOutsideCaller = (): (TStackFrame | undefined) => {

	let mySrc: (string | undefined) = undef

	const lFrames = Array.from(allStackFrames())
	return fromFSM(
		lFrames,
		[
			// --- state 0
			(frame: TStackFrame): TState => {
				const {source} = frame
				if (source) {
					mySrc = source
					return 1
				}
				else {
					return 0
				}
			},

			// --- state 1
			(frame: TStackFrame): TState => {
				const {source} = frame
				if (source && (source !== mySrc)) {
					throw frame
				}
				else {
					return 1
				}
			}
			],
		(finalState: TState) => {
			return undef
		},
		{})
}

