export const inFunc = (funcName: string): boolean => {

	const lFrames = Array.from(allStackFrames())
	assert((lFrames.length > 0), "No stack frames in inFunc()")
	const frame = lFrames[0]
	return (frame.type === 'function') && (frame.name === funcName)
}

// ---------------------------------------------------------------------------

export const deeplyInFunc = (funcName: string): boolean => {

	for (const frame of allStackFrames()) {
		if ((frame.type === 'function') && (frame.name === funcName)) {
			return true
		}
	}
	return false
}

